#### Example 1: Avro Schema with Semantic Version and Deprecation

```json
{
  "type": "record",
  "name": "ClaimSubmittedEvent",
  "namespace": "com.healthcare.claims.events",
  "version": "1.6.0",
  "doc": "Claim submission event published when provider submits claim for adjudication. Version 1.6.0 adds optional prior authorization reference.",
  "fields": [
    {
      "name": "claimId",
      "type": "string",
      "doc": "Unique claim identifier (UUID format)"
    },
    {
      "name": "memberId",
      "type": "string",
      "doc": "Member identifier from eligibility system"
    },
    {
      "name": "providerNpi",
      "type": "string",
      "doc": "National Provider Identifier (10-digit)"
    },
    {
      "name": "claimAmount",
      "type": "long",
    },
    {
      "name": "serviceDate",
      "type": "long",
      "logicalType": "timestamp-millis",
      "doc": "Date of service (epoch milliseconds)"
    },
    {
      "name": "diagnosisCodes",
      "type": {
        "type": "array",
        "items": "string"
      },
      "doc": "ICD-10 diagnosis codes (array of strings like ['E11.9', 'I10'])"
    },
    {
      "name": "legacyPaymentMethod",
      "type": ["null", "string"],
      "default": null,
      "doc": "DEPRECATED (2025-01-15): Use paymentMethodCode enum instead. Will be removed in v2.0 (2025-07-01)"
    },
    {
      "name": "paymentMethodCode",
      "type": [
        "null",
        {
          "type": "enum",
          "name": "PaymentMethod",
          "symbols": ["ACH", "WIRE", "CHECK", "CARD"]
        }
      ],
      "default": null,
      "doc": "Payment method enum (added v1.5.0)"
    },
    {
      "name": "priorAuthorizationId",
      "type": ["null", "string"],
      "default": null,
      "doc": "Prior authorization reference number if applicable (added v1.6.0)"
    },
    {
      "name": "metadata",
      "type": {
        "type": "record",
        "name": "EventMetadata",
        "fields": [
          {"name": "timestamp", "type": "long", "logicalType": "timestamp-millis"},
          {"name": "source", "type": "string"},
          {"name": "correlationId", "type": "string"}
        ]
      },
      "doc": "Event metadata for tracing and audit"
    }
  ]
}
```

